//! DO-282B $RS(48,34)$ Reed-Solomon forward error correction decoder.
//!
//! RTCA DO-282B specifies Reed-Solomon coding over $GF(2^8)$ generated by primitive polynomial
//! `0x11D`. The UAT downlink format uses $RS(48,34)$ ($N=48, K=34, 2t=14$).
//!
//! Evaluates syndromes, solves error locators via Berlekamp-Massey, searches roots via Chien
//! search, and resolves magnitudes via Forney's algorithm with zero heap allocations.

use aerofoil_common::DecodeError;

use crate::gf::{EXP_TABLE, gf_add, gf_inv, gf_mul, gf_pow};

/// Total codeword length for DO-282B UAT downlink $RS(48,34)$.
pub const RS_BLOCK_LEN: usize = 48;
/// Data symbol count for DO-282B UAT downlink $RS(48,34)$.
pub const RS_DATA_LEN: usize = 34;
/// Parity symbol count ($2t$) for DO-282B UAT downlink $RS(48,34)$.
pub const RS_PARITY_LEN: usize = 14;
/// Maximum number of correctable symbol errors ($t$).
pub const RS_MAX_CORRECTABLE: usize = 7;
/// First consecutive root index ($FCR$) in index form.
pub const RS_FCR: usize = 120;

/// Zero-allocation DO-282B $RS(48,34)$ Reed-Solomon decoder.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Rs48_34;

impl Rs48_34 {
    /// Decodes and corrects errors in a 48-byte UAT frame in-place.
    pub fn decode(frame: &mut [u8; RS_BLOCK_LEN]) -> Result<u8, DecodeError> {
        let (syn, has_errors) = Self::calc_syndromes(frame);
        if !has_errors {
            return Ok(0);
        }

        let (c, deg_c) = Self::berlekamp_massey(&syn).ok_or(DecodeError::UncorrectableRs)?;
        let (err_locs, roots, count) =
            Self::chien_search(&c, deg_c).ok_or(DecodeError::UncorrectableRs)?;
        let omega = Self::calc_evaluator(&syn, &c, deg_c);

        for k in 0..count {
            let err_val = Self::forney_value(&omega, &c, deg_c, roots[k])
                .ok_or(DecodeError::UncorrectableRs)?;
            frame[err_locs[k]] ^= err_val;
        }

        let (_, residual_errors) = Self::calc_syndromes(frame);
        if residual_errors {
            return Err(DecodeError::UncorrectableRs);
        }
        Ok(count as u8)
    }

    /// Evaluates the 14 syndromes $S_0 \dots S_{13}$ over the 48-byte frame.
    #[must_use]
    pub fn calc_syndromes(frame: &[u8; RS_BLOCK_LEN]) -> ([u8; RS_PARITY_LEN], bool) {
        let mut syn = [0u8; RS_PARITY_LEN];
        let mut has_errors = false;
        for (i, s) in syn.iter_mut().enumerate() {
            let root = EXP_TABLE[RS_FCR + i];
            let mut acc = 0u8;
            for &byte in frame.iter() {
                acc = gf_add(gf_mul(acc, root), byte);
            }
            *s = acc;
            if acc != 0 {
                has_errors = true;
            }
        }
        (syn, has_errors)
    }

    fn berlekamp_massey(syn: &[u8; RS_PARITY_LEN]) -> Option<([u8; 15], usize)> {
        let (mut c, mut b) = ([0u8; 15], [0u8; 15]);
        c[0] = 1;
        b[0] = 1;
        let (mut l, mut m, mut b_val) = (0usize, 1usize, 1u8);

        for n in 0..RS_PARITY_LEN {
            let mut d = syn[n];
            for i in 1..=l {
                d = gf_add(d, gf_mul(c[i], syn[n - i]));
            }
            if d == 0 {
                m += 1;
            } else {
                let factor = gf_mul(d, gf_inv(b_val)?);
                let mut t = c;
                for i in 0..=(RS_PARITY_LEN - m) {
                    if b[i] != 0 {
                        t[i + m] = gf_add(t[i + m], gf_mul(factor, b[i]));
                    }
                }
                if 2 * l <= n {
                    l = n + 1 - l;
                    b = c;
                    b_val = d;
                    m = 1;
                } else {
                    m += 1;
                }
                c = t;
            }
        }

        if l > RS_MAX_CORRECTABLE {
            None
        } else {
            Some((c, l))
        }
    }

    fn chien_search(c: &[u8; 15], deg: usize) -> Option<([usize; 7], [u8; 7], usize)> {
        let mut err_locs = [0usize; 7];
        let mut roots = [0u8; 7];
        let mut count = 0usize;

        for j in 0..RS_BLOCK_LEN {
            let p = (255 - (47 - j)) % 255;
            let x = EXP_TABLE[p];
            let mut val = 0u8;
            let mut x_pow = 1u8;
            for &coeff in c.iter().take(deg + 1) {
                val = gf_add(val, gf_mul(coeff, x_pow));
                x_pow = gf_mul(x_pow, x);
            }
            if val == 0 {
                if count >= RS_MAX_CORRECTABLE {
                    return None;
                }
                err_locs[count] = j;
                roots[count] = x;
                count += 1;
            }
        }

        if count == deg {
            Some((err_locs, roots, count))
        } else {
            None
        }
    }

    fn calc_evaluator(syn: &[u8; 14], c: &[u8; 15], deg: usize) -> [u8; 14] {
        let mut omega = [0u8; 14];
        for i in 0..14 {
            let mut acc = 0u8;
            let limit = if i < deg { i } else { deg };
            for j in 0..=limit {
                acc = gf_add(acc, gf_mul(syn[i - j], c[j]));
            }
            omega[i] = acc;
        }
        omega
    }

    fn forney_value(omega: &[u8; 14], c: &[u8; 15], deg: usize, x_inv: u8) -> Option<u8> {
        let mut num = 0u8;
        let mut x_pow = 1u8;
        for &om in omega.iter() {
            num = gf_add(num, gf_mul(om, x_pow));
            x_pow = gf_mul(x_pow, x_inv);
        }

        let mut den = 0u8;
        let x_pow2 = gf_mul(x_inv, x_inv);
        let mut curr_x = 1u8;
        let mut i = 1;
        while i <= deg {
            den = gf_add(den, gf_mul(c[i], curr_x));
            curr_x = gf_mul(curr_x, x_pow2);
            i += 2;
        }

        let den_inv = gf_inv(den)?;
        let factor = gf_pow(x_inv, RS_FCR - 1);
        Some(gf_mul(gf_mul(num, factor), den_inv))
    }
}

/// Convenience free function to decode a 48-byte UAT frame in-place.
#[inline]
pub fn decode_rs_48_34(frame: &mut [u8; RS_BLOCK_LEN]) -> Result<u8, DecodeError> {
    Rs48_34::decode(frame)
}
